TLM.f("Tempora/Pasc6-6",{"officium":"Sabbato in Vigilia Pentecostes","rule":["Gloria","omit Commemoratio","no Credo","Prefatio=Spiritu=hodierna die;","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Evangelium non appropriatum","ex Tempora/Pasc5-4;","Gloria","Credo","Gloria","Credo","Prefatio=Asc","Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc6-0","from":{"Commemoratio Oratio":"Tempora/Pasc6-0","Commemoratio Secreta":"Tempora/Pasc6-0","Commemoratio Postcommunio":"Tempora/Pasc6-0"},"sections":{"Introitus":[{"k":"ref","la":"Ezek 36:23; 36:24; 36:25-26"},{"k":"text","la":"Cum sanctificátus fúero in vobis, congregábo vos de univérsis terris: et effúndam super vos aquam mundam, et mundabímini ab ómnibus inquinaméntis vestris: et dabo vobis spíritum novum, allelúja, allelúja"},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cum sanctificátus fúero in vobis, congregábo vos de univérsis terris: et effúndam super vos aquam mundam, et mundabímini ab ómnibus inquinaméntis vestris: et dabo vobis spíritum novum, allelúja, allelúja"}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut claritatis tuæ super nos splendor effúlgeat; et lux tuæ lucis corda eórum, qui per grátiam tuam renáti sunt, Sancti Spíritus illustratióne confírmet."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolorum."},{"k":"ref","la":"Acts 19:1-8"},{"k":"text","la":"In diébus illis: Factum est, cum Apóllo esset Corínthi, ut Paulus, peragrátis superióribus pártibus, veníret Ephesum et inveníret quosdam discípulos: dixítque ad eos: Si Spíritum Sanctum accepístis credéntes? At illi dixérunt ad eum: Sed neque, si Spíritus Sanctus est, audívimus. Ille vero ait: In quo ergo baptizáti estis? Qui dixérunt: In Joannis baptísmate. Dixit autem Paulus: Joánnes baptizávit baptísmo pœniténtiæ pópulum, dicens: In eum, qui ventúrus esset post ipsum, ut créderent, hoc est in Jesum. His audítis, baptizáti sunt in nómine Dómini Jesu. Et cum imposuísset illis manus Paulus, venit Spíritus Sanctus super eos, et loquebántur linguis, et prophetábant. Erant autem omnes viri fere duódecim. Introgréssus autem synagógam, cum fidúcia loquebátur per tres menses, dísputans et suádens de regno Dei."}],"Graduale":[{"k":"text","la":"Allelúja"},{"k":"ref","la":"Ps 106:1"},{"k":"text","la":"Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericordia ejus.","mark":"V"},{"k":"ref","la":"Ps 116:1-2"},{"k":"text","la":"Laudáte Dóminum, omnes gentes: et collaudáte eum, omnes pópuli,"},{"k":"text","la":"Quóniam confirmáta est super nos misericórdia ejus: et véritas Dómini manet in ætérnum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joannes 14:15-21"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si dilígitis me, mandáta mea serváte. Et ego rogábo Patrem, et alium Paráclitum dabit vobis, ut máneat vobíscum in ætérnum, Spíritum veritátis, quem mundus non potest accípere, quia non videt eum nec scit eum. Vos autem cognoscétis eum: quia apud vos manébit et in vobis erit. Non relínquam vos órphanos: véniam ad vos. Adhuc módicum: et mundus me jam non videt. Vos autem vidétis me, quia ego vivo, et vos vivétis. In illo die vos cognoscétis, quia ego sum in Patre meo, et vos in me, et ego in vobis. Qui habet mandáta mea et servat ea: ille est, qui díligit me. Qui autem díligit me, diligétur a Patre meo: et ego díligam eum, et manifestábo ei meípsum."}],"Offertorium":[{"k":"ref","la":"Ps 103:30-31"},{"k":"text","la":"Emítte Spíritum tuum, et creabúntur, et renovábis fáciem terræ: sit glória Dómini in sǽcula, allelúja."}],"Secreta":[{"k":"text","la":"Múnera, quǽsumus, Dómine, obláta sanctífica: et corda nostra Sancti Spíritus illustratióne emúnda."},{"k":"macro","name":"Per Dominum eiusdem"}],"Communio":[{"k":"ref","la":"Joannes 7:37-39"},{"k":"text","la":"Ultimo festivitátis die dicébat Jesus: Qui in me credit, flúmina de ventre ejus fluent aquæ vivæ: hoc autem dixit de Spíritu, quem acceptúri erant credéntes in eum, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Sancti Spíritus, Dómine, corda nostra mundet infúsio: et sui roris íntima aspersióne fecúndet."},{"k":"macro","name":"Per Dominum eiusdem"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Ascensionis"},{"k":"text","la":"Concéde, quǽsumus, oninípotens Deus: ut, qui hodiérna die Unigénitum tuum, Redemptórem nostrum, ad cœlos ascendísse crédimus; ipsi quoque mente in cœléstibus habitémus."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Ascensionis"},{"k":"text","la":"Súscipe, Dómine, múnera, quæ pro Fílii tui gloriósa Ascensióne deférimus: et concéde propítius; ut a præséntibus perículis liberémur, et ad vitam perveniámus ætérnam."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Ascensionis."},{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens et miséricors Deus: ut, quæ visibílibus mystériis suménda percépimus, invisíbili consequámur efféctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b2793c5a0267ec3":{"t":"Ez 36, 23, 24 i 25-26, Ps 33, 2\n(Ez 36, 23, 24 et 25-26) Kada me budete častili, skupit ću vas iz svih zemalja i izlit ću na vas čistu vodu i očistit ćete se od svih svojih zloća. I dat ću vam duh novi, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 33, 2). Blagoslivljam Gospodina u svako vrijeme. Uvijek je njegova hvala u mojim ustima.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ez 36, 23, 24 et 25-26) Kada me budete častili, skupit ću vas iz svih zemalja i izlit ću na vas čistu vodu i očistit ćete se od svih svojih zloća. I dat ću vam duh novi, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ezek. 36, 23-16). Kada me budete častili, skupit ću vas iz svih zemalja i izlit ću na vas čistu vodu i očistit ćete se od svih svojih zloća; 1 dat ću vam duh novi, aleluja, aleluja (Ps, 33, 2). Blagosivam Gospodina u svako vrijeme, uvijek je hvala njegova u ustima mojim. Slava Ocu . . . Kad me budete ...","knRef":"Kniewald 1942, str. 338–339 (snimka 170) (OCR)"},"8de000e8eea8a41c":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da nad nama zasja sjaj tvoje jasnoće i da svjetlo tvoje svjetlosti rasvjetljenjem Duha Svetoga učvrsti srca onih koji su tvojom milošću preporođeni.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da nad ] nama zasja sjaj jasnosti Tvoje i da svijetlo Tvoje ' svjetlosti rasvjetljenjem Duha Svetoga učvrsti srca onih, koji su Tvojom milošću preporođeni, po G. n. . . . u jedinstvu istoga Duha ...","knRef":"Kniewald 1942, str. 338–339 (snimka 170) (OCR)"},"108d014cd5584e9e":{"t":"Dj 19, 1-9\nČitanje Djela apostolskih. U one dane, dok je Apolon bio u Korintu, Pavao je obišao gornje krajeve i dođe u Efez gdje nađe neke učenike i upita ih: Kada ste postali vjernici? Jeste li primili Duha Svetoga? Ali mu oni odgovore: Nismo ni čuli da postoji Duh Sveti. On ih upita: Kakav ste dakle krst primili? Odgovore: Ivanov krst. Pavao na to reče: Ivan je dijelio krst pokore govoreći narodu, neka vjeruje u onoga koji dolazi za njim, to jest u Isusa. Kad su to čuli, bili su kršteni u ime Gospodina Isusa. I kad je Pavao na njih položio ruke, siđe na njih Duh Sveti i govorili su jezike i proricali. Bilo je svih oko dvanaest ljudi. A kad je ušao u zbornicu, tri je mjeseca slobodno govorio, učio i uvjeravao o Božjem kraljevstvu.","kn":"Čitanje Djela apostolskih (.19, 1-8). U one dane, dok je Apolon bio u Korintu, Pavao je obišao gornje krajeve i dođe u Efez, gdje nađe neke učenike 1 upita ih: Kada ste postali vjernici, jeste li primili Duha Svetoga? Ali mu oni odgovore; Nijesmo ni čuli, da postoji Duh Sveti. On ih upita; Kakav ste dakle krst primili? Odgovore: Ivanov krst. Pavao na to reče: Ivan je dijelio krst pokore govoreći narodu, neka vjeruju u onoga, koji dolazi za njim, to jest, u Isusa. Kad su to čuli, bili su kršteni u ime Gospodina Isusa. I kad je Pavao na njih Duhovi ložio ruke, siđe na njih Duh Sveti i govorili EU jezike i proricali. Bilo je svih oko dvanaest ljudi. A kad je ušao u zbornicu, tri je mjeseca slobodno govorio, učio i uvjeravao o Božjem kraljevstvu.","knRef":"Kniewald 1942, str. 338–339 (snimka 170) (OCR)"},"12a3542bd33b0c8f":{"t":"Ps 106, 1\n<i>Aleluja</i>.\nslavite Gospodina jer je dobar, jer je do vijeka milosrđe njegovo.\n\nPs 116, 1-2\nHvalite Gospodina, sva plemena! Hvalite ga svi narodi. Jer je silno nad nama milosrđe njegovo, i istina Gospodnja ostaje dovijeka.","kn":"(Ps. 116, 1, 2). Hvalite Gospodina sva plemena, hvalite ga svi narodi, jer je silno nad nama njegovo milosrđe i istina Gospodnja ostaje dovijeka.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"e33cd6aa0d3a5277":{"t":"Iv 14, 15-21\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Ako me ljubite, držite moje zapovijedi. A ja ću moliti Oca koji će vam dati drugoga Utješitelja da ostane s vama zauvijek, Duha istine koga svijet ne može primiti jer niti ga vidi niti ga pozna. Ali vi ćete ga poznati jer će kod vas ostati i bit će u vama. Neću vas ostaviti sirotama! Doći ću k vama. Još malo i svijet me više neće vidjeti. Ali vi ćete me vidjeti jer ja živim i vi ćete živjeti. Onog ćete dana upoznati da sam ja u svom Ocu, a vi u meni i ja u vama. Tko ima moje zapovijedi i drži ih, taj je koji me ljubi. A tko mene ljubi, bit će ljubljen od moga Oca. Ja ću ga ljubiti i njemu ću se objaviti.","kn":"t Slijedi sveto evanđelje po Ivanu (14, 15-21). U ono vrijeme reče Isus .svojim učenicima: Ako me ljubite, držite moje zapovijedi. A ja ću moliti Oca, koji će vam dati drugoga Utješitelja, da ostane s vama za uvijek, Duha istine, kojega svijet ne može primiti, jer niti ga vidi niti ga pozna. Ali vi čete ga poznati, jer će kod vas ostati i bit će u vama. Ne ću vas ostaviti sirotama: doći ču k vama. Još malo i svijet me više ne će vidjeti. Ali vi ćete me vidjeti, jer ja živim i vi ćete živjeti. Onog ćete dana upoznati, da sam ja u svom Ocu, a vi u meni i ja u vama. Tko ima moje zapovijedi i drži ih, taj je, koji me ljubi. A tko mene ljubi, bit će ljubljen od moga Oca, i ja ću ga ljubiti i njemu ću se objaviti.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"9bfdb1b766b3fbcc":{"t":"Ps 103, 30-31\nPošalji Duha svojega i postat će novi svijet i obnovit ćeš lice zemlje. Neka je dovijeka slava Gospodnja, <i>aleluja</i>.","kn":"(Ps. 103, 30, 31). Salješ Duh svoj i postaju i obnavljaš lice zemlje; neka je dovijeka slava Gospodnja, aleluja.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"8a23e3366dd2990d":{"t":"Posveti, molimo, Gospodine, prinesene darove a naša srca očisti svjetlošću Duha Svetoga.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, posveti prikazane darove 1 očisti naša srca prosviječenjem Duha Svetoga, po G. n, I. K.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi. Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, koji je uzašao nad sva nebesa i sjeo s desne Tvoje i na današnji dan izlio obećanoga Duha Svetoga na Božje posinke. Zato kliče čitav svijet i svemir pun veselja. A i višnje moći i anđeoske vlasti pjevaju pjesmu Tvoje slave govoreći bez prestanka:","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"8bc929149414d0a7":{"t":"Iv 7, 37-39\nU posljednji veliki dan blagdana govorio je Isus: Tko vjeruje u me, u njemu će proteći potoci žive vode. A ovo reče za Duha kojega su imali primiti oni koji vjeruju u njega, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 7, 37, 39). U posljednji veliki dan blagdana govoraše Isus: Tko vjeruje U mene, rijeke će žive vode proteći iz njega. A ovo reče za Duha, kojega su imali primiti om, koji vjeruju u njega, aleluja, aleluja.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"0ed7897a863e81f5":{"t":"<i>Pomolimo se</i>.\nSrca naša, Gospodine, očistio dolazak Duha Svetoga i oplodio ih svojom nutarnjom rosom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da dolazak Duha Svetoga očisti naša srca i oplodi ih nutarnjom blagošću svoje rose. Po G. n. I. K. ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"}}});
